14	
15	// Daily sweep that nudges brand professionals stuck early in the onboarding
16	// funnel (still in BrandStatus::Onboarding or ShopifyLinked) at day 3, 10,
17	// and 30 since signup. One in-app notification per (brand, milestone),
18	// deduped by NotificationPublisher's insertOrIgnore on dedupe_key — so the
19	// sweep is safely re-runnable and each brand gets at most three nudges total.
20	class NudgeStuckOnboardingJob implements ShouldQueue
21	{
22	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
23	
24	    public int $tries = 3;
25	
26	    public int $timeout = 300;
27	
28	    /**
29	     * Day-since-signup milestones to nudge at. Each entry defines the day
30	     * window, the notification severity, and the title/body copy. Order
31	     * isn't significant — we run a separate query per milestone.
32	     *
33	     * @var array<int, array{day: int, severity: string, title: string, body: string}>
34	     */
35	    private const MILESTONES = [
36	        [
37	            'day' => 3,
38	            'severity' => 'Info',
39	            'title' => 'Finish setting up your brand',
40	            'body' => 'Connect Shopify to start running affiliate campaigns. It takes about 5 minutes.',
41	        ],
42	        [
43	            'day' => 10,
44	            'severity' => 'Info',
45	            'title' => 'Need a hand with setup?',
46	            'body' => 'Your brand is still waiting on setup. Reply to this notification or visit the dashboard if you need help.',
47	        ],
48	        [
49	            'day' => 30,
50	            'severity' => 'Warning',
51	            'title' => "Your brand isn't live yet",
52	            'body' => "It's been a month since signup and your brand still isn't connected. Finish setup to start earning.",
53	        ],
54	    ];
55	
56	    public function __construct()
57	    {
58	        $this->onQueue('notifications');
59	    }
60	
61	    public function handle(NotificationPublisher $publisher): void
62	    {
63	        foreach (self::MILESTONES as $milestone) {
64	            $this->sweepMilestone($publisher, $milestone);
65	        }
66	    }
67	
68	    /**
69	     * @param  array{day: int, severity: string, title: string, body: string}  $milestone
70	     */
71	    private function sweepMilestone(NotificationPublisher $publisher, array $milestone): void
72	    {
73	        $day = $milestone['day'];
74	
75	        // 24-hour window: brands whose created_at falls between (now - day - 1)
76	        // and (now - day). Catches each brand exactly once per milestone, even
77	        // if the sweep runs slightly off-schedule. Combined with the per-day
78	        // dedupe key, no brand ever gets the same milestone nudge twice.
79	        $windowStart = now()->subDays($day + 1);
80	        $windowEnd = now()->subDays($day);
81	
82	        // LEFT JOIN brand_profiles: a freshly-signed-up brand may not have a
83	        // brand_profiles row yet (created lazily on first status sync). Treat
84	        // null as Onboarding — that cohort is exactly who we most want to nudge.
85	        DB::table('core.professionals as p')
86	            ->leftJoin('brand.brand_profiles as bp', 'bp.professional_id', '=', 'p.id')
87	            ->where('p.professional_type', 'brand')
88	            ->whereNull('p.deleted_at')
89	            ->whereBetween('p.created_at', [$windowStart, $windowEnd])
90	            ->where(function ($q): void {
91	                $q->whereNull('bp.brand_status')
92	                    ->orWhereIn('bp.brand_status', [
93	                        BrandStatus::Onboarding->value,
94	                        BrandStatus::ShopifyLinked->value,
95	                    ]);
96	            })
97	            ->select(['p.id', 'p.first_name', 'p.display_name'])
98	            ->orderBy('p.id')
99	            ->chunkById(500, function ($chunk) use ($publisher, $day, $milestone) {
100	                foreach ($chunk as $row) {
101	                    try {
102	                        $proId = trim((string) ($row->id ?? ''));
103	                        if ($proId === '') {
104	                            continue;
105	                        }
106	
107	                        $publisher->publish(
108	                            professionalId: $proId,
109	                            frontendType: $milestone['severity'],
110	                            category: 'profile_tasks',
111	                            title: $milestone['title'],
112	                            body: $milestone['body'],
113	                            dedupeKey: "onboarding.nudge.{$proId}.day_{$day}",
114	                            ctaUrl: '/account/overview',
115	                            primaryActionLabel: 'Continue setup',
116	                            retentionConfigKey: 'profile_task',
117	                        );
118	                    } catch (\Throwable $e) {
119	                        Log::warning('NudgeStuckOnboardingJob failed for professional', [
120	                            'professional_id' => $row->id ?? null,
121	                            'day' => $day,
122	                            'message' => $e->getMessage(),
123	                        ]);
124	                    }
125	                }
126	            }, 'p.id', 'id');
127	    }
128	
129	    public function failed(\Throwable $e): void
130	    {
131	        Log::error('NudgeStuckOnboardingJob failed', [
132	            'message' => $e->getMessage(),
133	        ]);
134	    }
135	}
