15	// V2: Weekly sales/commission rollup notification for all active professionals. Runs on scheduled cron.
16	class SendWeeklyAnalyticsNotificationJob implements ShouldQueue
17	{
18	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
19	
20	    public int $tries = 2;
21	
22	    public int $timeout = 300;
23	
24	    public function __construct()
25	    {
26	        $this->onQueue('notifications');
27	    }
28	
29	    public function handle(NotificationPublisher $publisher): void
30	    {
31	        $yearWeek = now()->format('o-W'); // ISO year + week number
32	        // Window is [now-7d 00:00, now 00:00) so "last 7 days" never includes today.
33	        $windowStart = now()->subDays(7)->startOfDay();
34	        $windowEnd = now()->startOfDay();
35	
36	        DB::table('core.professionals')
37	            ->where('status', 'active')
38	            ->whereNull('deleted_at')
39	            ->orderBy('id')
40	            ->chunkById(200, function ($professionals) use ($publisher, $yearWeek, $windowStart, $windowEnd): void {
41	                $ids = $professionals->pluck('id')->all();
42	
43	                // Per-affiliate weekly orders + commission_cents from
44	                // commerce.orders. Excludes stub/cancelled/voided/refunded so
45	                // we never tell affiliates about a sale that won't pay out.
46	                // One batched query per chunk preserves the prior <=1
47	                // query/chunk contract enforced by
48	                // SendWeeklyAnalyticsNotificationJobQueryCountTest.
49	                $metricsByPro = DB::table('commerce.orders')
50	                    ->whereIn('affiliate_professional_id', $ids)
51	                    ->whereNotIn('status', Order::EXCLUDED_FROM_AGGREGATES)
52	                    ->where('occurred_at', '>=', $windowStart)
53	                    ->where('occurred_at', '<', $windowEnd)
54	                    ->select('affiliate_professional_id')
55	                    ->selectRaw('COUNT(*) as orders')
56	                    ->selectRaw('COALESCE(SUM(commission_cents), 0) as commission_cents')
57	                    ->groupBy('affiliate_professional_id')
58	                    ->get()
59	                    ->keyBy('affiliate_professional_id');
60	
61	                foreach ($professionals as $professional) {
62	                    try {
63	                        $metrics = $metricsByPro->get($professional->id);
64	                        $this->notifyProfessional($publisher, $professional, $metrics, $yearWeek);
65	                    } catch (\Throwable $e) {
66	                        Log::warning('Weekly analytics notification failed', [
67	                            'professional_id' => $professional->id,
68	                            'message' => $e->getMessage(),
69	                        ]);
70	                    }
71	                }
72	            });
73	    }
74	
75	    public function failed(\Throwable $e): void
76	    {
77	        report($e);
78	
79	        Log::error('SendWeeklyAnalyticsNotificationJob permanently failed', [
80	            'error' => $e->getMessage(),
81	        ]);
82	    }
83	
84	    private function notifyProfessional(
85	        NotificationPublisher $publisher,
86	        object $professional,
87	        ?object $metrics,
