26	
27	    // Generous timeout: the partial index keeps the scan tight, but the
28	    // chunk loop voids ledger entries inside a transaction per payout.
29	    public int $timeout = 300;
30	
31	    public function __construct()
32	    {
33	        $this->onQueue('stripe');
34	    }
35	
36	    /** Backoff between retries: short for the first, longer for the second. */
37	    public function backoff(): array
38	    {
39	        return [60, 180];
40	    }
