21	    // dispatches one ExecuteCommissionPayoutJob per batch. Stripe API calls happen
22	    // inside those child jobs, not here — so the timeout can be short.
23	    //
24	    // Retry guards:
25	    //   1. processEligiblePayouts re-dispatches any pending/collecting/transferring
26	    //      batches, so transient failures in child jobs are picked up next run.
27	    //   2. createPayoutBatch filters accrual entries on whereNull('payout_id') so
28	    //      we can't double-create a batch for the same ledger rows.
29	    //   3. ExecuteCommissionPayoutJob uses idempotent resume logic in processPayoutBatch
30	    //      — each step checks the payout's current status before executing.
31	    public int $tries = 3;
32	
33	    public int $timeout = 60;
34	
35	    public function __construct()
36	    {
37	        $this->onQueue('stripe');
38	    }
39	
40	    /**
41	     * Backoff between retries in seconds. 1 minute for the first retry
42	     * (typical network blip), 3 minutes for the second (longer Stripe outage).
43	     */
44	    public function backoff(): array
45	    {
46	        return [60, 180];
47	    }
48	
49	    public function handle(CommissionPayoutService $payoutService, CommissionVoidService $voidService): void
50	    {
51	        Log::info('Starting commission payout processing', [
52	            'attempt' => $this->attempts(),
53	        ]);
54	
55	        try {
56	            $payoutStats = $payoutService->processEligiblePayouts();
57	        } catch (RateLimitException $e) {
58	            // Stripe 429: back off exponentially before requeueing so we don't
59	            // amplify API pressure across concurrent brand payouts.
60	            // release() avoids burning a retry attempt against a transient throttle.
61	            $delay = min(120 * (2 ** ($this->attempts() - 1)), 600);
62	            Log::warning('Stripe rate limit hit in payout orchestration, requeueing with backoff', [
63	                'delay_seconds' => $delay,
64	                'attempt' => $this->attempts(),
65	            ]);
66	            $this->release($delay);
67	
68	            return;
69	        }
70	
71	        Log::info('Commission payout processing complete', $payoutStats);
72	
73	        // Void commissions past their window for unconnected affiliates
74	        $voidStats = $voidService->processVoidableCommissions();
75	
76	        // Send warning notifications to affiliates approaching deadlines
77	        $warningStats = $voidService->sendGracePeriodWarnings();
78	
79	        if ($voidStats['voided_count'] > 0 || $warningStats['warnings_sent'] > 0) {
80	            Log::info('Commission void/warning processing complete', [
81	                ...$voidStats,
82	                ...$warningStats,
83	            ]);
84	        }
85	    }
86	
87	    public function failed(\Throwable $e): void
88	    {
89	        // Forward to Nightwatch so the daily payout orchestration failure
90	        // is observable as a named exception, not a generic queue event.
91	        // Log::error gives a structured breadcrumb in cloud logs even if
92	        // Nightwatch is offline.
93	        report($e);
94	
95	        Log::error('Commission payout job failed after all retries', [
96	            'message' => $e->getMessage(),
97	        ]);
98	    }
99	}
