14	
15	// Daily sweep that nudges brand professionals stuck early in the onboarding
16	// funnel (still in BrandStatus::Onboarding or ShopifyLinked) at day 3, 10,
17	// and 30 since signup. One in-app notification per (brand, milestone),
18	// deduped by NotificationPublisher's insertOrIgnore on dedupe_key — so the
19	// sweep is safely re-runnable and each brand gets at most three nudges total.
20	// Scheduled: daily at 09:00 UTC via routes/console.php.
21	class NudgeStuckOnboardingJob implements ShouldQueue
22	{
23	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
24	
25	    public int $tries = 3;
26	
27	    public int $timeout = 300;
28	
29	    /**
30	     * Day-since-signup milestones to nudge at. Each entry defines the day
31	     * window, the notification severity, and the title/body copy. Order
32	     * isn't significant — we run a separate query per milestone.
33	     *
34	     * @var array<int, array{day: int, severity: string, title: string, body: string}>
35	     */
36	    private const MILESTONES = [
37	        [
38	            'day' => 3,
39	            'severity' => 'Info',
40	            'title' => 'Finish setting up your brand',
41	            'body' => 'Connect Shopify to start running affiliate campaigns. It takes about 5 minutes.',
42	        ],
43	        [
44	            'day' => 10,
45	            'severity' => 'Info',
46	            'title' => 'Need a hand with setup?',
47	            'body' => 'Your brand is still waiting on setup. Reply to this notification or visit the dashboard if you need help.',
48	        ],
49	        [
50	            'day' => 30,
51	            'severity' => 'Warning',
52	            'title' => "Your brand isn't live yet",
53	            'body' => "It's been a month since signup and your brand still isn't connected. Finish setup to start earning.",
54	        ],
55	    ];
56	
57	    public function __construct()
58	    {
59	        $this->onQueue('notifications');
60	    }
61	
62	    public function handle(NotificationPublisher $publisher): void
63	    {
64	        foreach (self::MILESTONES as $milestone) {
65	            $this->sweepMilestone($publisher, $milestone);
66	        }
67	    }
68	
69	    /**
70	     * @param  array{day: int, severity: string, title: string, body: string}  $milestone
71	     */
72	    private function sweepMilestone(NotificationPublisher $publisher, array $milestone): void
73	    {
74	        $day = $milestone['day'];
75	
76	        // 24-hour window: brands whose created_at falls between (now - day - 1)
77	        // and (now - day). Catches each brand exactly once per milestone, even
78	        // if the sweep runs slightly off-schedule. Combined with the per-day
79	        // dedupe key, no brand ever gets the same milestone nudge twice.
80	        $windowStart = now()->subDays($day + 1);
81	        $windowEnd = now()->subDays($day);
82	
83	        // LEFT JOIN brand_profiles: a freshly-signed-up brand may not have a
84	        // brand_profiles row yet (created lazily on first status sync). Treat
85	        // null as Onboarding — that cohort is exactly who we most want to nudge.
86	        DB::table('core.professionals as p')
87	            ->leftJoin('brand.brand_profiles as bp', 'bp.professional_id', '=', 'p.id')
88	            ->where('p.professional_type', 'brand')
89	            ->whereNull('p.deleted_at')
90	            ->whereBetween('p.created_at', [$windowStart, $windowEnd])
91	            ->where(function ($q): void {
92	                $q->whereNull('bp.brand_status')
93	                    ->orWhereIn('bp.brand_status', [
94	                        BrandStatus::Onboarding->value,
95	                        BrandStatus::ShopifyLinked->value,
96	                    ]);
97	            })
98	            ->select(['p.id', 'p.first_name', 'p.display_name'])
99	            ->orderBy('p.id')
100	            ->chunkById(500, function ($chunk) use ($publisher, $day, $milestone) {
101	                foreach ($chunk as $row) {
102	                    try {
103	                        $proId = trim((string) ($row->id ?? ''));
104	                        if ($proId === '') {
105	                            continue;
106	                        }
107	
108	                        $publisher->publish(
109	                            professionalId: $proId,
110	                            frontendType: $milestone['severity'],
111	                            category: 'profile_tasks',
112	                            title: $milestone['title'],
113	                            body: $milestone['body'],
114	                            dedupeKey: "onboarding.nudge.{$proId}.day_{$day}",
115	                            ctaUrl: '/account/overview',
116	                            primaryActionLabel: 'Continue setup',
117	                            retentionConfigKey: 'profile_task',
118	                        );
119	                    } catch (\Throwable $e) {
120	                        Log::warning('NudgeStuckOnboardingJob failed for professional', [
121	                            'professional_id' => $row->id ?? null,
122	                            'day' => $day,
123	                            'message' => $e->getMessage(),
124	                        ]);
125	                    }
126	                }
127	            }, 'p.id', 'id');
128	    }
129	
130	    public function failed(\Throwable $e): void
131	    {
132	        Log::error('NudgeStuckOnboardingJob failed', [
133	            'message' => $e->getMessage(),
134	        ]);
135	    }
136	}
