15	// Weekly sales/commission rollup notification for all active professionals.
16	// Scheduled: every Monday at 09:00 UTC via routes/console.php.
17	class SendWeeklyAnalyticsNotificationJob implements ShouldQueue
18	{
19	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
20	
21	    public int $tries = 2;
22	
23	    public int $timeout = 300;
24	
25	    public function __construct()
26	    {
27	        $this->onQueue('notifications');
28	    }
29	
30	    public function handle(NotificationPublisher $publisher): void
31	    {
32	        $yearWeek = now()->format('o-W'); // ISO year + week number
33	        // Window is [now-7d 00:00, now 00:00) so "last 7 days" never includes today.
34	        $windowStart = now()->subDays(7)->startOfDay();
35	        $windowEnd = now()->startOfDay();
36	
37	        DB::table('core.professionals')
38	            ->where('status', 'active')
39	            ->whereNull('deleted_at')
40	            ->orderBy('id')
41	            ->chunkById(200, function ($professionals) use ($publisher, $yearWeek, $windowStart, $windowEnd): void {
42	                $ids = $professionals->pluck('id')->all();
43	
44	                // Per-affiliate weekly orders + commission_cents from
45	                // commerce.orders. Excludes stub/cancelled/voided/refunded so
46	                // we never tell affiliates about a sale that won't pay out.
47	                // One batched query per chunk preserves the prior <=1
48	                // query/chunk contract enforced by
49	                // SendWeeklyAnalyticsNotificationJobQueryCountTest.
50	                $metricsByPro = DB::table('commerce.orders')
51	                    ->whereIn('affiliate_professional_id', $ids)
52	                    ->whereNotIn('status', Order::EXCLUDED_FROM_AGGREGATES)
53	                    ->where('occurred_at', '>=', $windowStart)
54	                    ->where('occurred_at', '<', $windowEnd)
55	                    ->select('affiliate_professional_id')
56	                    ->selectRaw('COUNT(*) as orders')
57	                    ->selectRaw('COALESCE(SUM(commission_cents), 0) as commission_cents')
58	                    ->groupBy('affiliate_professional_id')
59	                    ->get()
60	                    ->keyBy('affiliate_professional_id');
61	
62	                foreach ($professionals as $professional) {
63	                    try {
64	                        $metrics = $metricsByPro->get($professional->id);
65	                        $this->notifyProfessional($publisher, $professional, $metrics, $yearWeek);
66	                    } catch (\Throwable $e) {
67	                        Log::warning('Weekly analytics notification failed', [
68	                            'professional_id' => $professional->id,
69	                            'message' => $e->getMessage(),
70	                        ]);
71	                    }
72	                }
73	            });
74	    }
75	
76	    public function failed(\Throwable $e): void
77	    {
78	        report($e);
79	
80	        Log::error('SendWeeklyAnalyticsNotificationJob permanently failed', [
81	            'error' => $e->getMessage(),
82	        ]);
83	    }
84	
85	    private function notifyProfessional(
86	        NotificationPublisher $publisher,
87	        object $professional,
88	        ?object $metrics,
89	        string $yearWeek,
90	    ): void {
91	        $orders = (int) ($metrics?->orders ?? 0);
92	        $commissionCents = (int) ($metrics?->commission_cents ?? 0);
