14	
15	// Polls Twitch and Kick for live status of all blocks with live_check_enabled=true.
16	// Scheduled: every 2 minutes via routes/console.php.
17	class CheckStreamingLiveStatusJob implements ShouldQueue
18	{
19	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
20	
21	    public int $tries = 1;
22	
23	    public int $timeout = 90;
24	
25	    public function handle(LiveStatusPoller $poller): void
26	    {
27	        try {
28	            $kickRateLimited = Redis::exists('streaming:kick:rate_limited');
29	        } catch (\Throwable $e) {
30	            Log::error('streaming.redis_unavailable', ['message' => $e->getMessage()]);
31	            report($e);
32	
33	            return;
34	        }
35	
36	        if ($kickRateLimited) {
37	            Log::warning('streaming: skipping Kick — rate limited from previous cycle');
38	        }
39	
40	        $streamingPlatforms = config('partna.streaming_platforms', []);
41	
42	        /** @var array<string, list<string>> $handlesByPlatform */
43	        $handlesByPlatform = array_fill_keys($streamingPlatforms, []);
44	
45	        // block_group='links' (NOT block_type='link') is the links/sections discriminator
46	        // in site.blocks. All other queries in the codebase use block_group.
47	        Block::query()
48	            ->where('block_group', 'links')
49	            ->whereRaw("settings->>'live_check_enabled' = ?", ['true'])
50	            ->whereNull('deleted_at')
51	            ->where('is_active', true)
52	            ->chunkById(500, function ($blocks) use (&$handlesByPlatform, $streamingPlatforms): void {
53	                foreach ($blocks as $block) {
54	                    $settings = is_array($block->settings) ? $block->settings : [];
55	                    $platform = $settings['platform'] ?? null;
56	                    $handle = $settings['handle'] ?? null;
57	
58	                    if (
59	                        $platform
60	                        && $handle
61	                        && in_array($platform, $streamingPlatforms, true)
62	                    ) {
63	                        $handlesByPlatform[$platform][] = $handle;
64	                    }
65	                }
66	            });
67	
68	        foreach ($handlesByPlatform as $platform => $handles) {
69	            if (empty($handles)) {
70	                continue;
71	            }
72	
73	            if ($platform === 'kick' && $kickRateLimited) {
74	                continue;
75	            }
76	
77	            try {
78	                $poller->poll($platform, $handles);
79	            } catch (\Throwable $e) {
80	                Log::error('streaming.poll_error', [
81	                    'platform' => $platform,
82	                    'message' => $e->getMessage(),
83	                ]);
84	            }
85	        }
86	    }
87	
88	    public function failed(\Throwable $e): void
89	    {
90	        Log::error('streaming.job_failed', ['message' => $e->getMessage()]);
91	    }
92	}
