23	{
24	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
25	
26	    public int $tries = 3;
27	
28	    // Generous timeout: the partial index keeps the scan tight, but the
29	    // chunk loop voids ledger entries inside a transaction per payout.
30	    public int $timeout = 300;
31	
32	    public function __construct()
33	    {
34	        $this->onQueue('stripe');
35	    }
36	
37	    /** Backoff between retries: short for the first, longer for the second. */
38	    public function backoff(): array
39	    {
40	        return [60, 180];
41	    }
42	
43	    public function handle(CommissionVoidService $voidService): void
44	    {
45	        $stats = $voidService->processExpiredPayouts();
46	
47	        // Always emit a heartbeat — silence here would mask a stuck scheduler.
48	        // Promote to notice when real cancellations land so they stand out
49	        // from routine zero-action passes (matches markPendingFunding's pattern).
50	        if ($stats['cancelled_count'] > 0 || $stats['voided_entries'] > 0) {
51	            Log::notice('Expired payout void processing complete', $stats);
52	        } else {
53	            Log::info('Expired payout void processing complete', $stats);
54	        }
55	    }
56	
57	    public function failed(\Throwable $e): void
58	    {
