5	use App\Services\Stripe\CommissionPayoutService;
6	use App\Services\Stripe\CommissionVoidService;
7	use Illuminate\Bus\Queueable;
8	use Illuminate\Contracts\Queue\ShouldQueue;
9	use Illuminate\Foundation\Bus\Dispatchable;
10	use Illuminate\Queue\InteractsWithQueue;
11	use Illuminate\Queue\SerializesModels;
12	use Illuminate\Support\Facades\Log;
13	use Stripe\Exception\RateLimitException;
14	
15	// Batch-processes all eligible commission payouts via CommissionPayoutService.
16	// Scheduled: hourly via routes/console.php.
17	class ProcessCommissionPayoutsJob implements ShouldQueue
18	{
19	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
20	
21	    // This job is now a lightweight orchestrator: it creates payout batches and
22	    // dispatches one ExecuteCommissionPayoutJob per batch. Stripe API calls happen
23	    // inside those child jobs, not here — so the timeout can be short.
24	    //
25	    // Retry guards:
26	    //   1. processEligiblePayouts re-dispatches any pending/collecting/transferring
27	    //      batches, so transient failures in child jobs are picked up next run.
28	    //   2. createPayoutBatch filters accrual entries on whereNull('payout_id') so
29	    //      we can't double-create a batch for the same ledger rows.
30	    //   3. ExecuteCommissionPayoutJob uses idempotent resume logic in processPayoutBatch
31	    //      — each step checks the payout's current status before executing.
32	    public int $tries = 3;
33	
34	    public int $timeout = 60;
35	
36	    public function __construct()
37	    {
38	        $this->onQueue('stripe');
39	    }
40	
41	    /**
42	     * Backoff between retries in seconds. 1 minute for the first retry
43	     * (typical network blip), 3 minutes for the second (longer Stripe outage).
44	     */
45	    public function backoff(): array
46	    {
47	        return [60, 180];
48	    }
49	
50	    public function handle(CommissionPayoutService $payoutService, CommissionVoidService $voidService): void
51	    {
52	        Log::info('Starting commission payout processing', [
53	            'attempt' => $this->attempts(),
54	        ]);
55	
56	        try {
57	            $payoutStats = $payoutService->processEligiblePayouts();
58	        } catch (RateLimitException $e) {
59	            // Stripe 429: back off exponentially before requeueing so we don't
60	            // amplify API pressure across concurrent brand payouts.
61	            // release() avoids burning a retry attempt against a transient throttle.
62	            $delay = min(120 * (2 ** ($this->attempts() - 1)), 600);
63	            Log::warning('Stripe rate limit hit in payout orchestration, requeueing with backoff', [
64	                'delay_seconds' => $delay,
65	                'attempt' => $this->attempts(),
66	            ]);
67	            $this->release($delay);
68	
69	            return;
70	        }
71	
72	        Log::info('Commission payout processing complete', $payoutStats);
73	
74	        // Void commissions past their window for unconnected affiliates
75	        $voidStats = $voidService->processVoidableCommissions();
76	
77	        // Send warning notifications to affiliates approaching deadlines
78	        $warningStats = $voidService->sendGracePeriodWarnings();
79	
80	        if ($voidStats['voided_count'] > 0 || $warningStats['warnings_sent'] > 0) {
81	            Log::info('Commission void/warning processing complete', [
82	                ...$voidStats,
83	                ...$warningStats,
84	            ]);
85	        }
86	    }
87	
88	    public function failed(\Throwable $e): void
89	    {
90	        // Forward to Nightwatch so the daily payout orchestration failure
91	        // is observable as a named exception, not a generic queue event.
92	        // Log::error gives a structured breadcrumb in cloud logs even if
93	        // Nightwatch is offline.
94	        report($e);
95	
96	        Log::error('Commission payout job failed after all retries', [
97	            'message' => $e->getMessage(),
98	        ]);
99	    }
100	}
